9	// FAIL-SAFE: a live-safe results mapper must exist before live runs are
10	// allowed. toResultsDto is not one: it hard-codes synthetic facts. While this
11	// is null, deps.live is null whatever the environment says, so a live run can
12	// never spend money before a truthful mapper exists.
13	export const LIVE_RESULTS_MAPPER: ToResults | null = null;
14	
15	export function buildLiveDeps(
16	  config: LiveConfig,
17	  store: LiveStore,
18	  mapper: ToResults | null = LIVE_RESULTS_MAPPER,
19	): LiveDeps {
20	  return {
21	    store,
22	    hmacSecret: config.hmacSecret,
23	    live: mapper === null ? null : config.live,
24	    now: () => new Date(),
25	    ...realFactories,
26	    toResults: (result, ctx) => {
27	      if (ctx.mode === "synthetic") return toResultsDto(result);
28	      if (mapper === null) throw new Error("no live results mapper");
29	      return mapper(result, ctx);
30	    },
31	  };
32	}
