34	interface Connected {
35	  readonly config: LiveConfig;
36	  readonly store: LiveStore;
37	}
38	
39	let connect: (() => Promise<Connected>) | null = null;
40	
41	async function connected(): Promise<Connected | null> {
42	  const read = readLiveConfig(process.env);
43	  if (!read.ok) return null;
44	  connect ??= createMemoizedConnector(async () => {
45	    const { store } = await connectStore(read.config.databaseUrl);
46	    return { config: read.config, store };
47	  });
48	  return connect();
49	}
50	
51	export const runtime: LiveRuntime = {
52	  async getDeps() {
53	    const c = await connected();
54	    return c === null ? null : buildLiveDeps(c.config, c.store);
55	  },
56	  async getStore() {
57	    return (await connected())?.store ?? null;
58	  },
59	};
