1	// Presentation DTO for the live beta, for both synthetic and live codes.
2	// Built field by field from an improved-pipeline result: nothing is spread
3	// from pipeline objects, and every displayed message is fixed text chosen by
4	// code (see safe-text.ts). It reuses the results page's ProspectDto and
5	// MetricsDto without changing ResultsDto or toResultsDto.
6	//
7	// Its signature matches the server's injected results mapper:
8	// (result, { mode, model }) => results.
9	
10	import type { LlmCostSummary, PipelineResult, PipelineStatus } from "../../../core/agent/types";
11	import {
12	  type MetricsDto,
13	  metricsDto,
14	  type ProspectDto,
15	  toProspectDto,
16	} from "../../results/_lib/presentation";
17	import { issueMessage, safeCode, safeProspect } from "./safe-text";
18	
19	export type LiveMode = "synthetic" | "live";
20	
21	export interface LiveResultsContext {
22	  readonly mode: LiveMode;
23	  // The model the run used: the fake model's name in synthetic mode.
24	  readonly model: string;
25	}
26	
27	// How the provider cost was arrived at.
28	// simulated_fixture_prices: synthetic mode. FixtureProvider's per-record
29	//   prices; nothing was called or charged.
30	// estimated_per_record: live mode. Records searched and enriched, priced at
31	//   the measured per-record rates. An estimate, not an invoice.
32	export type ProviderCostBasis = "simulated_fixture_prices" | "estimated_per_record";
33	
34	// What kind of known model cost model_usd holds, from llm_cost.calls_by_basis.
35	// It describes the known costs only; completeness is model_complete's job.
36	// none: no external model cost. No model calls in live mode; always in
37	//   synthetic mode, whose fake-model calls call no external model.
38	// gateway_reported: every known cost was reported by the gateway.
39	// estimated: every known cost was estimated from token usage at the
40	//   fallback rates.
41	// mixed: known costs of both kinds.
42	// unavailable: model calls were made but no call has a known cost.
43	export type ModelCostBasis = "none" | "gateway_reported" | "estimated" | "mixed" | "unavailable";
44	
45	export interface LiveCostDto {
46	  readonly provider_usd: number;
47	  readonly provider_basis: ProviderCostBasis;
48	  // The known model cost, usage.llm_cost.known_usd, as reported (0 in
49	  // synthetic mode). Read it with model_basis and model_complete: 0 with
50	  // basis "unavailable" means unknown, not free.
51	  readonly model_usd: number;
52	  readonly model_basis: ModelCostBasis;
53	  // True only when every model call has a known cost (and when there were
54	  // none). When false, model_usd is a lower bound, never a total.
55	  readonly model_complete: boolean;
56	  // Model calls whose cost is not known, including calls the basis counts
57	  // fail to account for.
58	  readonly model_calls_unavailable: number;
59	}
60	
61	export interface LiveResultsDto {
62	  readonly run: {
63	    readonly status: PipelineStatus;
64	    readonly mode: LiveMode;
65	    readonly data_source: "fixtures" | "crustdata";
66	    readonly model: string;
67	    readonly fact_provider: "fixture" | "crustdata";
68	    readonly limits: {
69	      readonly max_search_results: number;
70	      readonly max_enrichments: number;
71	      readonly max_llm_calls_per_run: number;
72	    };
73	    readonly counts: {
74	      readonly searched: number;
75	      readonly enriched: number;
76	      readonly delivered: number;
77	      readonly assessed: number;
78	      readonly model_calls: number;
79	    };
80	    readonly cost: LiveCostDto;
81	  };
82	  readonly metrics: MetricsDto | null;
83	  readonly issues: readonly { readonly code: string; readonly message: string }[];
84	  readonly prospects: readonly ProspectDto[];
85	}
86	
87	const MAX_MODEL_NAME_LENGTH = 64;
88	
89	function modelName(model: string): string {
90	  const clean = model.replace(/[^\w.:/-]+/g, " ").trim().slice(0, MAX_MODEL_NAME_LENGTH);
91	  return clean === "" ? "unknown" : clean;
92	}
93	
94	function count(n: number): number {
95	  return Number.isFinite(n) && n > 0 ? Math.floor(n) : 0;
96	}
97	
98	type ModelCost = Pick<LiveCostDto, "model_usd" | "model_basis" | "model_complete" | "model_calls_unavailable">;
99	
100	// Synthetic mode has no external model cost. Its fake-model calls are logical
101	// calls inside the app, so FakeLlmClient's simulated cost is not reported.
102	export const SYNTHETIC_MODEL_COST: ModelCost = {
103	  model_usd: 0,
104	  model_basis: "none",
105	  model_complete: true,
106	  model_calls_unavailable: 0,
107	};
108	
109	export function modelCost(cost: LlmCostSummary, modelCalls: number): ModelCost {
110	  const gateway = count(cost.calls_by_basis.gateway_reported);
111	  const estimated = count(cost.calls_by_basis.estimated);
112	  const recorded = gateway + estimated + count(cost.calls_by_basis.unavailable);
113	  // Calls the basis counts do not account for are unavailable too, so a
114	  // missing record never disappears or reads as "no model calls".
115	  const unavailable = count(cost.calls_by_basis.unavailable) + Math.max(0, count(modelCalls) - recorded);
116	
117	  // The basis describes the known costs only.
118	  let basis: ModelCostBasis;
119	  if (gateway > 0 && estimated > 0) basis = "mixed";
120	  else if (gateway > 0) basis = "gateway_reported";
121	  else if (estimated > 0) basis = "estimated";
122	  else basis = unavailable > 0 ? "unavailable" : "none";
123	
124	  return {
125	    model_usd: cost.known_usd,
126	    model_basis: basis,
127	    // Every call must have a known cost, and the pipeline must agree.
128	    model_complete: unavailable === 0 && (basis === "none" || cost.complete),
129	    model_calls_unavailable: unavailable,
130	  };
131	}
132	
133	export function toLiveResultsDto(result: PipelineResult, ctx: LiveResultsContext): LiveResultsDto {
134	  const live = ctx.mode === "live";
135	  return {
136	    run: {
137	      status: result.status,
138	      mode: live ? "live" : "synthetic",
139	      data_source: live ? "crustdata" : "fixtures",
140	      model: modelName(ctx.model),
141	      fact_provider: live ? "crustdata" : "fixture",
142	      limits: {
143	        max_search_results: result.usage.max_search_results,
144	        max_enrichments: result.usage.max_enrichments,
145	        max_llm_calls_per_run: result.usage.max_llm_calls_per_run,
146	      },
147	      counts: {
148	        searched: result.run.counts.searched,
149	        enriched: result.run.counts.enriched,
150	        delivered: result.run.counts.delivered,
151	        assessed: result.prospects.filter((p) => p.assessment.status === "assessed").length,
152	        model_calls: result.run.counts.llm_calls,
153	      },
154	      cost: {
155	        provider_usd: result.usage.provider.cost_usd,
156	        provider_basis: live ? "estimated_per_record" : "simulated_fixture_prices",
157	        ...(live ? modelCost(result.usage.llm_cost, result.run.counts.llm_calls) : SYNTHETIC_MODEL_COST),
158	      },
159	    },
160	    metrics: result.metrics ? metricsDto(result.metrics) : null,
161	    issues: result.issues.map((i) => ({ code: safeCode(i.code), message: issueMessage(i.code) })),
162	    prospects: result.prospects.map((p) => safeProspect(toProspectDto(p))),
163	  };
164	}
