43	// ---- Response contract ----------------------------------------------------
44	
45	// What the injected mapper returns is opaque here. The mapper owns the shape
46	// of the results and must not copy upstream text into them.
47	export interface ResultsContext {
48	  readonly mode: CodeMode;
49	  readonly model: string;
50	}
51	
52	export type ToResults = (result: PipelineResult, ctx: ResultsContext) => unknown;
53	
54	export type LiveBody =
55	  | {
56	      readonly status: "ok";
57	      readonly mode: CodeMode;
58	      readonly results: unknown;
59	      readonly usage: { readonly runsRemaining: number };
60	      readonly notices: readonly string[];
61	    }
62	  | { readonly status: "invalid_request"; readonly field: string; readonly message: string }
63	  | { readonly status: "rate_limited"; readonly retryAfterSeconds: number; readonly message: string }
64	  | { readonly status: "live_disabled"; readonly message: string }
65	  | { readonly status: "invalid_code"; readonly message: string }
66	  | { readonly status: "no_runs_left"; readonly message: string }
67	  | { readonly status: "run_in_progress"; readonly message: string }
68	  | { readonly status: "budget_exhausted"; readonly message: string }
69	  | { readonly status: "run_failed"; readonly message: string }
70	  | { readonly status: "live_unavailable"; readonly message: string };
71	
72	export interface LiveOutcome {
73	  readonly httpStatus: 200 | 400 | 401 | 403 | 409 | 429 | 502 | 503;
74	  readonly body: LiveBody;
75	}
