178	        ...(search_validation !== undefined ? { search_validation } : {}),
179	        ...(validation !== undefined ? { validation } : {}),
180	        ...(p.checks !== undefined
181	          ? {
182	              checks: {
183	                ...p.checks,
184	                assessment: scrubCheck(p.checks.assessment),
185	                ...(p.checks.claims !== undefined ? { claims: scrubCheck(p.checks.claims) } : {}),
186	              },
187	            }
188	          : {}),
