269	export async function runLive(
270	  request: { readonly code: unknown; readonly icp: unknown },
271	  ip: string,
272	  deps: LiveDeps,
273	): Promise<LiveOutcome> {
274	  const checked = validateRequest(request);
275	  if (!checked.ok) {
276	    return respond(400, { status: "invalid_request", field: checked.field, message: checked.message });
277	  }
278	  const valid = checked.value;
279	
280	  let reserved: Reserved;
281	  try {
282	    const { store, hmacSecret } = deps;
283	    const ipHash = hashIp(ip, hmacSecret);
284	
285	    const rate = await store.hit(`ip:${ipHash}`, deps.now(), IP_WINDOW_SECONDS, IP_LIMIT);
286	    if (!rate.allowed) return rateLimited(rate.retryAfterSeconds);
287	
288	    const result = await store.reserveRun(hashCode(valid.code, hmacSecret), deps.now(), RUN_LOCK_SECONDS);
289	    if (!result.ok) {
290	      switch (result.reason) {
291	        case "invalid_code":
292	        case "disabled": {
293	          const bad = await store.hit(`badcode:${ipHash}`, deps.now(), BAD_CODE_WINDOW_SECONDS, BAD_CODE_LIMIT);
294	          if (!bad.allowed) return rateLimited(bad.retryAfterSeconds);
295	          return simple(401, "invalid_code");
296	        }
297	        case "no_runs_left":
298	          return simple(403, "no_runs_left");
299	        case "run_in_progress":
300	          return simple(409, "run_in_progress");
301	        default:
302	          return simple(503, "live_unavailable");
303	      }
304	    }
305	    reserved = { runId: result.runId, runsRemaining: result.runsRemaining, mode: result.mode };
306	  } catch {
307	    return simple(503, "live_unavailable");
308	  }
309	
310	  // From here a run exists: every exit must finish or release it.
311	  const { store } = deps;
312	
313	  // The kill switch only stops live-mode codes; synthetic codes never read it.
314	  if (reserved.mode === "live") {
315	    // Keys missing or live not allowed by the runtime fail-safe: do not attempt the run.
316	    if (deps.live === null) {
317	      await giveBack(store, reserved.runId);
318	      return simple(503, "live_disabled");
319	    }
320	    let enabled: boolean;
321	    try {
322	      enabled = await store.isLiveEnabled();
323	    } catch {
324	      await giveBack(store, reserved.runId);
325	      return simple(503, "live_unavailable");
326	    }
327	    if (!enabled) {
328	      await giveBack(store, reserved.runId);
329	      return simple(503, "live_disabled");
330	    }
331	  }
332	
333	  const settle = async (op: () => Promise<void>) => {
334	    try {
335	      await op();
336	    } catch {
337	      // The outcome is already decided; a store failure cannot change it.
338	    }
339	  };
340	  const failed = async (outcome: Partial<RunOutcome> = {}): Promise<LiveOutcome> => {
341	    await settle(() =>
342	      store.finishRun(reserved.runId, {
343	        status: "failed",
344	        searched: 0,
345	        enriched: 0,
346	        providerCostUsd: 0,
347	        modelCostUsd: 0,
348	        errorCategory: "run_failed",
349	        ...outcome,
350	      }),
351	    );
352	    return simple(502, "run_failed");
353	  };
354	
355	  try {
356	    return reserved.mode === "synthetic"
357	      ? await runSynthetic(reserved, deps, failed)
358	      : await runLiveMode(valid, reserved, deps, failed);
359	  } catch {
360	    return failed();
361	  }
362	}
363	
364	async function giveBack(store: LiveStore, runId: string): Promise<void> {
365	  try {
366	    await store.releaseRun(runId);
367	  } catch {
368	    // Nothing more can be done; the lock expires on its own.
369	  }
370	}
