385	interface Reserved {
386	  readonly runId: string;
387	  readonly runsRemaining: number;
388	  readonly mode: CodeMode;
389	}
390	
391	type Failed = (outcome?: Partial<RunOutcome>) => Promise<LiveOutcome>;
392	
393	async function runSynthetic(reserved: Reserved, deps: LiveDeps, failed: Failed): Promise<LiveOutcome> {
394	  const run = await runSyntheticPipeline("synthetic", deps.synthetic ?? syntheticDependencies);
395	  if (run.kind !== "ok") return failed();
396	  const { result } = run;
397	  const searched = result.usage.provider.searched;
398	  const enriched = result.usage.provider.enriched;
399	  const results = deps.toResults(scrubResult(result), { mode: "synthetic", model: "fake" });
400	  await finishCompleted(deps.store, reserved.runId, {
401	    status: "completed",
402	    searched,
403	    enriched,
404	    providerCostUsd: 0,
405	    modelCostUsd: 0,
406	  });
407	  const notices = [...SYNTHETIC_NOTICES, ...noticesFromIssues(result.issues)];
408	  return respond(200, {
409	    status: "ok",
410	    mode: "synthetic",
411	    results,
412	    usage: { runsRemaining: reserved.runsRemaining },
413	    notices,
414	  });
415	}
